/**
 * Environment Detection Utilities
 *
 * Provides consistent environment detection across all surfaces (web, api, cli, vscode, mcp).
 *
 * CRITICAL: NODE_ENV is unreliable because Doppler sets it to "production" even locally.
 * Use DEPLOYMENT_ENV or hostname-based detection instead.
 *
 * @example
 * ```typescript
 * import { getDeploymentEnv, isDevelopment, getAnalyticsEnv } from '@vreko/infrastructure/environment';
 *
 * // Get the deployment environment
 * const env = getDeploymentEnv(); // 'development' | 'production'
 *
 * // Check if running in development
 * if (isDevelopment()) {
 *   logger.debug(...);
 * }
 *
 * // Get environment for analytics
 * const analyticsEnv = getAnalyticsEnv(); // { env: 'dev' | 'prod', surface: string }
 * ```
 */

export type DeploymentEnvironment = "development" | "staging" | "production";

export type AnalyticsEnvironment = "dev" | "prod";

export type Surface = "web" | "api" | "cli" | "vscode" | "mcp" | "daemon";

/**
 * Detect if running in local development environment
 *
 * Detection priority:
 * 1. DEPLOYMENT_ENV environment variable (explicit override)
 * 2. VERCEL_ENV or FLY_ALLOC_ID (cloud deployment = production)
 * 3. BETTER_AUTH_URL contains localhost (local dev server)
 * 4. Hostname is localhost/127.0.0.1/*.local (client-side)
 */
export function isDevelopment(): boolean {
	return getDeploymentEnv() === "development";
}

/**
 * Detect if running in production environment
 */
export function isProduction(): boolean {
	return getDeploymentEnv() === "production";
}

/**
 * Get the deployment environment
 *
 * Priority:
 * 1. DEPLOYMENT_ENV env var (explicit)
 * 2. CI + VERCEL/FLY = production
 * 3. localhost detection = development
 * 4. Default = production (safe default)
 */
export function getDeploymentEnv(): DeploymentEnvironment {
	// 1. Explicit override
	const explicitEnv = process.env.DEPLOYMENT_ENV;
	if (explicitEnv === "development" || explicitEnv === "staging" || explicitEnv === "production") {
		return explicitEnv;
	}

	// 2. Cloud deployment detection
	if (process.env.VERCEL || process.env.VERCEL_ENV || process.env.FLY_ALLOC_ID) {
		return "production";
	}

	// 3. Local development detection (server-side)
	const authUrl = process.env.BETTER_AUTH_URL || process.env.APP_URL || "";
	if (authUrl.includes("localhost") || authUrl.includes("127.0.0.1")) {
		return "development";
	}

	// 4. Client-side detection (browser)
	if (typeof window !== "undefined") {
		const hostname = window.location.hostname;
		if (
			hostname === "localhost" ||
			hostname === "127.0.0.1" ||
			hostname.endsWith(".local") ||
			hostname.endsWith(".test")
		) {
			return "development";
		}
	}

	// 5. CI detection (GitHub Actions, etc.)
	if (process.env.CI) {
		// CI without cloud deployment flags = likely testing/staging
		return "production";
	}

	// 6. Safe default
	return "production";
}

/**
 * Get analytics environment string (shorter format for PostHog)
 */
export function getAnalyticsEnv(): AnalyticsEnvironment {
	return getDeploymentEnv() === "development" ? "dev" : "prod";
}

/**
 * Get environment info for logging/debugging
 */
export function getEnvironmentInfo(): {
	deployment: DeploymentEnvironment;
	analytics: AnalyticsEnvironment;
	nodeEnv: string | undefined;
	isCi: boolean;
	isVercel: boolean;
	isFly: boolean;
	isLocalhost: boolean;
} {
	const deployment = getDeploymentEnv();
	return {
		deployment,
		analytics: deployment === "development" ? "dev" : "prod",
		nodeEnv: process.env.NODE_ENV,
		isCi: !!process.env.CI,
		isVercel: !!(process.env.VERCEL || process.env.VERCEL_ENV),
		isFly: !!process.env.FLY_ALLOC_ID,
		isLocalhost:
			(process.env.BETTER_AUTH_URL?.includes("localhost") ?? false) ||
			(typeof window !== "undefined" &&
				(window.location.hostname === "localhost" || window.location.hostname === "127.0.0.1")),
	};
}

/**
 * Detect current surface based on environment
 */
export function detectSurface(): Surface {
	// VS Code extension
	if (process.env.VSCODE_EXTENSION || typeof process.env.VSCODE_PID !== "undefined") {
		return "vscode";
	}

	// CLI
	if (process.env.VREKO_CLI || process.argv[1]?.includes("cli")) {
		return "cli";
	}

	// MCP server
	if (process.env.MCP_SERVER || process.env.MCP_MODE) {
		return "mcp";
	}

	// Daemon (local service)
	if (process.env.DAEMON_MODE || process.env.LOCAL_SERVICE) {
		return "daemon";
	}

	// API server
	if (process.env.API_SERVER || typeof process.env.PORT !== "undefined") {
		return "api";
	}

	// Web (client-side default)
	if (typeof window !== "undefined") {
		return "web";
	}

	// Server-side default
	return "api";
}

/**
 * Get super properties for PostHog analytics
 */
export function getAnalyticsSuperProperties(surface?: Surface): {
	env: AnalyticsEnvironment;
	surface: Surface;
} {
	return {
		env: getAnalyticsEnv(),
		surface: surface ?? detectSurface(),
	};
}
