/**
 * AgentSession  -  Provider-agnostic LLM instrumentation wrapper
 *
 * Provides unified observability across multiple LLM providers (Anthropic, OpenAI, Gemini, Ollama, etc.)
 * All agent calls go through this wrapper regardless of which LLM is used, ensuring consistent
 * telemetry attribution in Langfuse with provider and model as mandatory span attributes.
 *
 * Per OBS-PROVIDER-01: provider and model are mandatory fields on every Generation-type observation.
 */

import { createHash, randomUUID } from "node:crypto";
import { type ActionPayload, AgentAction, type AgentRole, LLMProvider } from "./vocabulary.js";
import { recordAction as emitAction, type RecordActionOptions } from "./wrapper.js";

export interface AgentSessionConfig {
	role: AgentRole;
	provider: LLMProvider;
	model: string;
	sessionId: string;
	traceId?: string;
	specId?: string;
}

export interface Tool {
	name: string;
	description?: string;
	parameters?: Record<string, unknown>;
}

export interface AgentSessionOptions {
	timeout?: number;
	maxRetries?: number;
}

export interface AgentResult {
	content: string;
	usage?: {
		inputTokens?: number;
		outputTokens?: number;
		totalTokens?: number;
	};
}

/**
 * Unified AgentSession wrapper for multi-LLM observability
 *
 * Wraps any LLM call (Anthropic, OpenAI, Gemini, Ollama, etc.) with consistent
 * telemetry instrumentation. Provider and model are always included as span
 * attributes per OBS-PROVIDER-01.
 *
 * Example usage:
 * ```ts
 * // Conductor using Claude Opus
 * const session = new AgentSession({
 *   role: "conductor",
 *   provider: LLMProvider.ANTHROPIC,
 *   model: "claude-opus-4-6",
 *   sessionId: "session-123"
 * });
 *
 * // Auditor using GPT-4o
 * const session = new AgentSession({
 *   role: "auditor",
 *   provider: LLMProvider.OPENAI,
 *   model: "gpt-4o",
 *   sessionId: "session-123"
 * });
 *
 * // Local model for grunt work
 * const session = new AgentSession({
 *   role: "auditor",
 *   provider: LLMProvider.OLLAMA,
 *   model: "llama3",
 *   sessionId: "session-123"
 * });
 *
 * const result = await session.run("Analyze this code", tools);
 * ```
 */
export class AgentSession {
	private readonly role: AgentRole;
	private readonly provider: LLMProvider;
	private readonly model: string;
	private readonly sessionId: string;
	private readonly specId: string | undefined;
	private readonly traceId: string;
	private readonly options: AgentSessionOptions;

	constructor(config: AgentSessionConfig, options: AgentSessionOptions = {}) {
		this.role = config.role;
		this.provider = config.provider;
		this.model = config.model;
		this.sessionId = config.sessionId;
		this.specId = config.specId;
		this.traceId = config.traceId || this.generateTraceId();
		this.options = {
			timeout: options.timeout ?? 30000,
			maxRetries: options.maxRetries ?? 3,
		};
	}

	/**
	 * Generate a consistent trace ID from session ID and role
	 */
	private generateTraceId(): string {
		const seed = `${this.sessionId}-${this.role}-${Date.now()}`;
		return randomUUID().replace(/-/g, "");
	}

	/**
	 * Run an LLM inference with telemetry instrumentation
	 *
	 * Records PLAN and DECIDE actions with provider and model attributes.
	 * Routes to the appropriate SDK based on provider.
	 */
	async run(prompt: string, options?: { tools?: Tool[]; maxTokens?: number }): Promise<AgentResult> {
		const startTime = Date.now();

		// Record PLAN action  -  hash prompt, never raw content (OBS-PROVIDER-01)
		await this.recordAction(AgentAction.PLAN, {
			description: `prompt[${this.hash(prompt).slice(0, 8)}]`,
			provider: this.provider,
			model: this.model,
		});

		try {
			// Route to the right SDK internally
			const result = await this.dispatch(prompt, options);

			// Record DECIDE action with output hash (OBS-PROVIDER-01)
			await this.recordAction(AgentAction.DECIDE, {
				decision: `output[${this.hash(result.content).slice(0, 8)}]`,
			});

			return result;
		} catch (error) {
			// Record error decision (OBS-PROVIDER-01)
			await this.recordAction(AgentAction.DECIDE, {
				decision: "error",
				rationale: error instanceof Error ? error.message : String(error),
			});
			throw error;
		}
	}

	/**
	 * Dispatch to the appropriate LLM SDK based on provider
	 */
	private async dispatch(prompt: string, options?: { tools?: Tool[]; maxTokens?: number }): Promise<AgentResult> {
		switch (this.provider) {
			case LLMProvider.ANTHROPIC:
				return this.runAnthropic(prompt, options);
			case LLMProvider.OPENAI:
				return this.runOpenAI(prompt, options);
			case LLMProvider.GEMINI:
				return this.runGemini(prompt, options);
			case LLMProvider.OLLAMA:
				return this.runOllama(prompt, options);
			default:
				// Unknown provider: use Anthropic as fallback for provenance
				return this.runAnthropic(prompt, options);
		}
	}

	/**
	 * Anthropic SDK integration
	 * TODO: Implement with @anthropic-ai/sdk
	 */
	private async runAnthropic(prompt: string, options?: { tools?: Tool[]; maxTokens?: number }): Promise<AgentResult> {
		throw new Error("Anthropic SDK integration not yet implemented");
	}

	/**
	 * OpenAI SDK integration
	 * TODO: Implement with openai package
	 */
	private async runOpenAI(prompt: string, options?: { tools?: Tool[]; maxTokens?: number }): Promise<AgentResult> {
		throw new Error("OpenAI SDK integration not yet implemented");
	}

	/**
	 * Google Gemini SDK integration
	 * TODO: Implement with @google/generative-ai
	 */
	private async runGemini(prompt: string, options?: { tools?: Tool[]; maxTokens?: number }): Promise<AgentResult> {
		throw new Error("Gemini SDK integration not yet implemented");
	}

	/**
	 * Ollama (local model) integration
	 * TODO: Implement with ollama package or HTTP API
	 */
	private async runOllama(prompt: string, options?: { tools?: Tool[]; maxTokens?: number }): Promise<AgentResult> {
		throw new Error("Ollama integration not yet implemented");
	}

	private async recordAction(
		action: AgentAction,
		payload: ActionPayload<typeof action>,
		opts?: Partial<RecordActionOptions>,
	): Promise<void> {
		await emitAction(action, payload as never, {
			traceId: this.traceId,
			agentRole: this.role,
			specId: this.specId,
			model: this.model,
			...opts,
		});
	}

	/**
	 * Hash sensitive content (prompts, outputs) before recording
	 * Uses SHA-256 for cryptographic hashing
	 */
	private hash(content: string): string {
		return createHash("sha256").update(content).digest("hex");
	}

	/**
	 * Get the trace ID for this session
	 */
	getTraceId(): string {
		return this.traceId;
	}

	/**
	 * Get the session ID
	 */
	getSessionId(): string {
		return this.sessionId;
	}

	/**
	 * Get provider and model for observability
	 */
	getProviderInfo(): { provider: LLMProvider; model: string } {
		return { provider: this.provider, model: this.model };
	}
}
