/**
 * Prometheus Metrics Module for Vreko
 *
 * Provides a centralized Prometheus registry with health check metrics.
 * Compatible with Fly.io managed Grafana at fly-metrics.net
 *
 * @module @vreko/infrastructure/prometheus
 */

import client from "prom-client";

// =============================================================================
// Registry Configuration
// =============================================================================

/**
 * Create a dedicated registry for Vreko metrics
 * This allows for clean separation from any default metrics
 */
export const registry = new client.Registry();

// Add default metrics (Node.js GC, memory, etc.)
// These are automatically collected by prom-client
const defaultMetrics = client.collectDefaultMetrics;
defaultMetrics({ register: registry });

// =============================================================================
// Health Check Metrics
// =============================================================================

/**
 * Health check status gauge
 * Values: 1 = healthy, 0 = unhealthy
 * Labels: service, check (liveness/readiness/startup)
 */
export const healthCheckStatus = new client.Gauge({
	name: "health_check_status",
	help: "Current health check status (1=healthy, 0=unhealthy)",
	labelNames: ["service", "check"] as const,
	registers: [registry],
});

/**
 * Health check failure counter
 * Increments each time a health check fails
 * Labels: service, check, reason
 */
export const healthCheckFailuresTotal = new client.Counter({
	name: "health_check_failures_total",
	help: "Total number of health check failures",
	labelNames: ["service", "check", "reason"] as const,
	registers: [registry],
});

/**
 * Health check duration histogram
 * Records how long health checks take
 * Labels: service, check
 */
export const healthCheckDurationSeconds = new client.Histogram({
	name: "health_check_duration_seconds",
	help: "Duration of health check execution in seconds",
	labelNames: ["service", "check"] as const,
	buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10],
	registers: [registry],
});

/**
 * Health check last success timestamp
 * Unix timestamp of last successful health check
 * Labels: service, check
 */
export const healthCheckLastSuccessTimestamp = new client.Gauge({
	name: "health_check_last_success_timestamp_seconds",
	help: "Unix timestamp of the last successful health check",
	labelNames: ["service", "check"] as const,
	registers: [registry],
});

