// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Record a health check result
 */
export function recordHealthCheck(
	service: string,
	check: "liveness" | "readiness" | "startup",
	status: "healthy" | "unhealthy" | "degraded",
	durationMs: number,
): void {
	const isHealthy = status === "healthy" ? 1 : 0;

	// Update status gauge
	healthCheckStatus.set({ service, check }, isHealthy);

	// Record duration
	healthCheckDurationSeconds.observe({ service, check }, durationMs / 1000);

	// Update timestamp if healthy
	if (status === "healthy") {
		healthCheckLastSuccessTimestamp.set({ service, check }, Date.now() / 1000);
	}

	// Increment failure counter if unhealthy
	if (status === "unhealthy") {
		healthCheckFailuresTotal.inc({ service, check, reason: "check_failed" });
	}
}

/**
 * Record readiness probe result
 */
export function recordReadinessProbe(service: string, isReady: boolean): void {
	readinessProbeStatus.set({ service }, isReady ? 1 : 0);
	if (isReady) {
		readinessProbeLastSuccessTimestamp.set({ service }, Date.now() / 1000);
	}
}

/**
 * Record startup completion
 */
export function recordStartupComplete(service: string, durationSeconds: number): void {
	startupProbeDurationSeconds.set({ service }, durationSeconds);
}

/**
 * Get metrics in Prometheus exposition format
 * This is what you return from the /metrics endpoint
 */
export async function getMetrics(): Promise<string> {
	return registry.metrics();
}

/**
 * Get content type for Prometheus metrics response
 */
export function getContentType(): string {
	return registry.contentType;
}

