/**
 * Graceful Shutdown Handler - 2026 Enterprise Pattern
 *
 * Implements proper graceful shutdown with:
 * - Connection draining
 * - Timeout handling
 * - Cleanup handler registration
 * - Health check integration
 *
 * @see https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/#pod-termination
 * @see https://fly.io/docs/blueprints/seamless-deployments/
 */

import type { Logger } from "../logging/logger.js";

export interface GracefulShutdownOptions {
	/** Logger instance */
	logger: Logger;
	/** Shutdown timeout in milliseconds (default: 25000ms to fit within 30s kill_timeout) */
	timeoutMs?: number;
	/** Health check marker file path (optional) */
	healthMarkerPath?: string;
}

export interface ShutdownHandler {
	/** Register a cleanup handler to be called during shutdown */
	register(handler: () => Promise<void>): void;
	/** Mark the service as ready (health checks will pass) */
	setReady(): void;
	/** Mark the service as not ready (health checks will fail) */
	setNotReady(): void;
	/** Initialize the shutdown handler (attach signal listeners) */
	init(): void;
	/** Check if the service is ready */
	isReady(): boolean;
	/** Check if shutdown is in progress */
	isShuttingDown(): boolean;
}

/**
 * Create a graceful shutdown handler
 *
 * 2026 Pattern: Implements proper graceful shutdown sequence:
 * 1. Set not ready (health checks fail, stop routing traffic)
 * 2. Wait briefly for in-flight requests to complete
 * 3. Run cleanup handlers in reverse order (LIFO)
 * 4. Force exit if timeout is reached
 */
export function createGracefulShutdown(options: GracefulShutdownOptions): ShutdownHandler {
	const { logger, timeoutMs = 25000, healthMarkerPath } = options;

	const cleanupHandlers: Array<() => Promise<void>> = [];
	let isShuttingDown = false;
	let isReady = false;

	/**
	 * Set readiness state (for health checks)
	 */
	function updateReadiness(ready: boolean): void {
		isReady = ready;

		// Optionally write health marker file for external checks
		if (healthMarkerPath) {
			try {
				if (ready) {
					// Write marker file to indicate ready
					// @ts-expect-error - Bun global may not exist
					globalThis.Bun?.write?.(healthMarkerPath, process.pid.toString());
				} else {
					// Remove marker file to indicate not ready
					// @ts-expect-error - Bun global may not exist
					globalThis.Bun?.write?.(healthMarkerPath, "");
				}
			} catch (error) {
				logger.debug("Health marker file operation failed", { error });
			}
		}
	}

	/**
	 * Execute shutdown sequence
	 */
	async function shutdown(signal: string): Promise<void> {
		if (isShuttingDown) {
			logger.warn("Shutdown already in progress, ignoring signal", { signal });
			return;
		}

		isShuttingDown = true;
		logger.info("Shutdown initiated", { signal, pid: process.pid });

		// Step 1: Mark as not ready immediately
		// This tells load balancers to stop routing new traffic
		updateReadiness(false);
		logger.info("Service marked as not ready, stopping new traffic");

		// Step 2: Wait briefly for in-flight requests
		// This is critical for zero-downtime deployments
		const drainTimeout = Math.min(5000, timeoutMs / 5);
		logger.info("Waiting for in-flight requests to complete", { drainTimeoutMs: drainTimeout });
		await new Promise((resolve) => setTimeout(resolve, drainTimeout));

		// Step 3: Run cleanup handlers in reverse order (LIFO)
		logger.info("Running cleanup handlers", { count: cleanupHandlers.length });

		const cleanupTimeout = timeoutMs - drainTimeout - 2000; // Leave 2s buffer
		const cleanupStart = Date.now();

		for (let i = cleanupHandlers.length - 1; i >= 0; i--) {
			const remainingTime = cleanupTimeout - (Date.now() - cleanupStart);
			if (remainingTime <= 0) {
				logger.warn("Cleanup timeout reached, some handlers may not have completed");
				break;
			}

			try {
				const handler = cleanupHandlers[i];
				const handlerTimeout = Math.min(remainingTime, 5000);

				// Run handler with timeout
				await Promise.race([
					handler(),
					new Promise((_, reject) => setTimeout(() => reject(new Error("Handler timeout")), handlerTimeout)),
				]);
			} catch (error) {
				logger.error("Cleanup handler error", { error, handlerIndex: i });
			}
		}

		logger.info("Shutdown complete", {
			durationMs: Date.now() - cleanupStart + drainTimeout,
		});

		process.exit(0);
	}

	// Force exit after timeout
	const forceExit = (): never => {
		logger.error("Forced exit due to timeout", { timeoutMs });
		process.exit(1);
	};

	return {
		register(handler: () => Promise<void>): void {
			cleanupHandlers.push(handler);
		},

		setReady(): void {
			updateReadiness(true);
		},

		setNotReady(): void {
			updateReadiness(false);
		},

		init(): void {
			// Handle termination signals
			const handleShutdown = (signal: string) => {
				shutdown(signal).catch((error) => {
					logger.error("Shutdown error", { error });
					process.exit(1);
				});

				// Set force exit timeout
				setTimeout(forceExit, timeoutMs);
			};

			process.on("SIGTERM", () => handleShutdown("SIGTERM"));
			process.on("SIGINT", () => handleShutdown("SIGINT"));

			// Handle uncaught errors
			process.on("uncaughtException", (error) => {
				logger.error("Uncaught exception, initiating shutdown", { error });
				handleShutdown("uncaughtException");
			});

			process.on("unhandledRejection", (reason) => {
				logger.error("Unhandled rejection, initiating shutdown", { reason });
				// Don't shutdown on unhandled rejection in production
				// Just log it - this is often recoverable
				if (process.env.NODE_ENV !== "production") {
					handleShutdown("unhandledRejection");
				}
			});

			logger.info("Graceful shutdown handler initialized", { timeoutMs });
		},

		isReady(): boolean {
			return isReady;
		},

		isShuttingDown(): boolean {
			return isShuttingDown;
		},
	};
}

/**
 * Server shutdown helper with connection draining
 */
export async function drainAndCloseServer(
	server: {
		close: () => Promise<void> | void;
		closeIdleConnections?: () => void;
		closeAllConnections?: () => void;
	},
	logger: Logger,
): Promise<void> {
	logger.info("Closing server...");

	// Step 1: Stop accepting new connections
	// server.close() stops accepting new connections but keeps existing ones
	const closePromise = server.close();

	// Step 2: Close idle connections immediately (Node 18.2.0+)
	if (server.closeIdleConnections) {
		logger.info("Closing idle connections...");
		server.closeIdleConnections();
	}

	// Step 3: Wait for active connections to finish or timeout
	const timeout = 10000; // 10 seconds
	await Promise.race([closePromise, new Promise((resolve) => setTimeout(resolve, timeout))]);

	// Step 4: Force close remaining connections (Node 18.2.0+)
	if (server.closeAllConnections) {
		logger.info("Force closing remaining connections...");
		server.closeAllConnections();
	}

	logger.info("Server closed");
}

/**
 * PreStop hook helper for containers
 * Call this when receiving shutdown signal to add additional delay
 * for load balancer deregistration
 */
export async function preStopDelay(ms = 5000): Promise<void> {
	// This delay allows the load balancer to detect the unhealthy state
	// and stop routing traffic before we start draining connections
	await new Promise((resolve) => setTimeout(resolve, ms));
}
