/**
 * Neon Database Client for Documentation Intelligence
 *
 * Wrapper around @neondatabase/serverless for the doc embeddings knowledgebase.
 * Provides connection pooling, query helpers, and type-safe interfaces.
 *
 * @module infrastructure/neon/client
 */

import { type NeonQueryFunction, neon, neonConfig } from "@neondatabase/serverless";

// ============================================================================
// TYPES
// ============================================================================

/**
 * Documentation embedding record
 */
export interface DocEmbedding {
	id: string;
	library: string;
	version: string;
	doc_type: "api_reference" | "security_pattern" | "best_practice" | "deprecation";
	chunk_text: string;
	embedding: number[];
	metadata: Record<string, unknown>;
	source_url: string | null;
	indexed_at: Date;
}

/**
 * Hybrid search result with similarity score
 */
export interface SearchResult {
	id: string;
	library: string;
	version: string;
	doc_type: string;
	chunk_text: string;
	metadata: Record<string, unknown>;
	source_url: string | null;
	similarity: number;
}

/**
 * Neon client configuration
 */
export interface NeonClientConfig {
	/** Neon connection string (pooled URL recommended for queries) */
	connectionString: string;
	/** Enable connection caching (default: true) */
	enableCache?: boolean;
}

// ============================================================================
// CLIENT
// ============================================================================

/**
 * Neon documentation intelligence client
 *
 * @example
 * ```typescript
 * const client = new NeonDocClient({
 *   connectionString: process.env.NEON_DATABASE_URL!
 * });
 *
 * const results = await client.hybridSearch(
 *   embedding,
 *   { library: 'react', version: '18.x', limit: 5 }
 * );
 * ```
 */
export class NeonDocClient {
	private sql: NeonQueryFunction<false, false>;

	constructor(config: NeonClientConfig) {
		// Enable connection caching (Neon handles pooling transparently)
		if (config.enableCache !== false) {
			neonConfig.fetchConnectionCache = true;
		}

		// Create query function
		this.sql = neon(config.connectionString);
	}

	/**
	 * Execute hybrid search against doc_embeddings
	 *
	 * @param queryEmbedding - 768-dim vector from text-embedding-3-small
	 * @param options - Search filters and limits
	 * @returns Ranked search results with similarity scores
	 */
	async hybridSearch(
		queryEmbedding: number[],
		options: {
			library?: string;
			version?: string;
			limit?: number;
			similarityThreshold?: number;
		} = {},
	): Promise<SearchResult[]> {
		if (queryEmbedding.length !== 768) {
			throw new Error(`Expected 768-dim embedding, got ${queryEmbedding.length}`);
		}

		const { library = null, version = null, limit = 5, similarityThreshold = 0.75 } = options;

		// Convert embedding to pgvector format
		const embeddingStr = `[${queryEmbedding.join(",")}]`;

		const results = await this.sql`
      SELECT * FROM hybrid_search(
        ${embeddingStr}::vector(768),
        ${library},
        ${version},
        ${limit},
        ${similarityThreshold}
      )
    `;

		return results as SearchResult[];
	}

	/**
	 * Insert a single doc embedding
	 *
	 * @param doc - Document embedding record
	 * @returns Inserted record ID
	 */
	async insertDoc(doc: Omit<DocEmbedding, "id" | "indexed_at">): Promise<string> {
		if (doc.embedding.length !== 768) {
			throw new Error(`Expected 768-dim embedding, got ${doc.embedding.length}`);
		}

		const embeddingStr = `[${doc.embedding.join(",")}]`;

		const result = await this.sql`
      INSERT INTO doc_embeddings (library, version, doc_type, chunk_text, embedding, metadata, source_url)
      VALUES (
        ${doc.library},
        ${doc.version},
        ${doc.doc_type},
        ${doc.chunk_text},
        ${embeddingStr}::vector(768),
        ${JSON.stringify(doc.metadata)},
        ${doc.source_url}
      )
      ON CONFLICT (library, version, chunk_text)
      DO UPDATE SET
        embedding = EXCLUDED.embedding,
        metadata = EXCLUDED.metadata,
        indexed_at = NOW()
      RETURNING id
    `;

		return result[0]?.id ?? "";
	}

	/**
	 * Batch insert doc embeddings (optimized for bulk ingestion)
	 *
	 * @param docs - Array of document embeddings
	 * @returns Count of inserted/updated records
	 */
	async batchInsertDocs(docs: Array<Omit<DocEmbedding, "id" | "indexed_at">>): Promise<number> {
		if (docs.length === 0) {
			return 0;
		}

		// Validate all embeddings are 768-dim
		for (const doc of docs) {
			if (doc.embedding.length !== 768) {
				throw new Error(`Expected 768-dim embedding, got ${doc.embedding.length}`);
			}
		}

		// Insert docs one by one (batch optimization can be added later with proper parameterization)
		let count = 0;
		for (const doc of docs) {
			await this.insertDoc(doc);
			count++;
		}

		return count;
	}

	/**
	 * Get embedding stats (total chunks, by library, etc.)
	 */
	async getStats(): Promise<{
		total: number;
		byLibrary: Record<string, number>;
		byDocType: Record<string, number>;
	}> {
		const totalResult = await this.sql`SELECT COUNT(*) as count FROM doc_embeddings`;
		const total = Number(totalResult[0]?.count ?? 0);

		const byLibraryResult = await this.sql`
      SELECT library, COUNT(*) as count 
      FROM doc_embeddings 
      GROUP BY library
    `;

		const byDocTypeResult = await this.sql`
      SELECT doc_type, COUNT(*) as count 
      FROM doc_embeddings 
      GROUP BY doc_type
    `;

		return {
			total,
			byLibrary: Object.fromEntries(byLibraryResult.map((r) => [r.library, Number(r.count)])),
			byDocType: Object.fromEntries(byDocTypeResult.map((r) => [r.doc_type, Number(r.count)])),
		};
	}
}
