/**
 * vocabulary.ts  -  Canonical Agent Action Vocabulary
 *
 * OBS-VOCAB-01: Defines the typed enum for all swarm-instrumented operations.
 * Every span emitted by a Vreko swarm agent MUST use a value from this enum.
 *
 * Adding a new verb requires:
 *   1. Add to this enum
 *   2. Update meta-canon.md §3.2
 *   3. Update ActionPayload discriminated union in wrapper.ts
 */

// ─── Agent Action Enum ────────────────────────────────────────────────────────

export enum AgentAction {
	// Reads
	SEARCH = "SEARCH",
	READ_FILE = "READ_FILE",
	LIST_DIR = "LIST_DIR",
	GREP = "GREP",
	// Writes
	WRITE_FILE = "WRITE_FILE",
	EDIT_FILE = "EDIT_FILE",
	DELETE_FILE = "DELETE_FILE",
	// Execution
	RUN_TEST = "RUN_TEST",
	RUN_BUILD = "RUN_BUILD",
	RUN_LINT = "RUN_LINT",
	RUN_SHELL = "RUN_SHELL",
	// VCS
	COMMIT = "COMMIT",
	REVERT = "REVERT",
	BRANCH = "BRANCH",
	MERGE = "MERGE",
	// Network / external
	HTTP_GET = "HTTP_GET",
	HTTP_POST = "HTTP_POST",
	MCP_CALL = "MCP_CALL",
	// Reasoning / control
	PLAN = "PLAN",
	REVIEW = "REVIEW",
	DECIDE = "DECIDE",
	ASK_USER = "ASK_USER",
	// Verification
	VERIFY_GATE = "VERIFY_GATE",
	SCORE_R = "SCORE_R",
	// Swarm pipeline events (meta-canon §3.2 additions)
	SEARCH_EXTERNAL = "SEARCH_EXTERNAL", // external web/GitHub search  -  only Auditor + Spec Writer
	FETCH_DOCS = "FETCH_DOCS", // library/API documentation retrieval via MCP
	CITE = "CITE", // record a citation in external-findings section
	GATE_OPEN = "GATE_OPEN", // conductor opens a human gate
	GATE_CLOSE = "GATE_CLOSE", // conductor closes a human gate (Q approval received)
	DISPATCH = "DISPATCH", // conductor assigns a spec to a worktree
	AUDIT_PHASE = "AUDIT_PHASE", // auditor runs Phase 1 internal or Phase 2 external audit
	SPEC_WRITE = "SPEC_WRITE", // spec writer authors a specification
	// Pipeline phase boundary events
	PHASE_START = "PHASE_START", // emitted when a pipeline stage begins
	PHASE_END = "PHASE_END", // emitted when a pipeline stage completes or fails
}

// ─── LLM Provider Enum ─────────────────────────────────────────────────────────
// OBS-PROVIDER-01: Provider and model are mandatory fields on Generation-type observations.

export enum LLMProvider {
	ANTHROPIC = "anthropic",
	OPENAI = "openai",
	GEMINI = "gemini",
	OLLAMA = "ollama",
	MISTRAL = "mistral",
	COHERE = "cohere",
	UNKNOWN = "unknown", // escape hatch  -  logs a warning, never silently accepted
}

// ─── Agent Role Enum ──────────────────────────────────────────────────────────

export enum AgentRole {
	SPEC_WRITER = "spec-writer",
	AUDITOR = "auditor",
	IMPLEMENTER = "implementer",
	ADVERSARIAL_REVIEWER = "adversarial-reviewer",
	CONDUCTOR = "conductor",
	DRIFT_DETECTOR = "drift-detector",
	GATEKEEPER = "gatekeeper",
	INTEGRATOR = "integrator",
	RESEARCHER = "researcher",
	DEVSECOPS = "devsecops",
	TECHNICAL_WRITER = "technical-writer",
	RELEASE_MANAGER = "release-manager",
	MASTER_COORDINATOR = "master-coordinator",
}

// ─── Action Payload Discriminated Union ───────────────────────────────────────
// OBS-VOCAB-03: TypeScript enforces required fields per action at the call site.

export type ActionPayload<A extends AgentAction> = A extends AgentAction.SEARCH
	? { query: string; scope?: string }
	: A extends AgentAction.READ_FILE
		? { path: string }
		: A extends AgentAction.LIST_DIR
			? { path: string }
			: A extends AgentAction.GREP
				? { pattern: string; path?: string }
				: A extends AgentAction.WRITE_FILE
					? {
							path: string;
							affectedPaths: string[]; // all paths written in this action, including path itself
							linesAdded?: number; // optional  -  populate if available from diff
							linesRemoved?: number;
						}
					: A extends AgentAction.EDIT_FILE
						? {
								path: string;
								affectedPaths: string[];
								linesAdded?: number;
								linesRemoved?: number;
							}
						: A extends AgentAction.DELETE_FILE
							? { path: string }
							: A extends AgentAction.RUN_TEST
								? { command: string; exitCode?: number }
								: A extends AgentAction.RUN_BUILD
									? { command: string; exitCode?: number }
									: A extends AgentAction.RUN_LINT
										? { command: string; exitCode?: number }
										: A extends AgentAction.RUN_SHELL
											? { command: string; exitCode?: number }
											: A extends AgentAction.COMMIT
												? {
														sha: string;
														message: string;
														affectedPaths: string[]; // full list of paths in the commit
														authorModel: string; // model string, e.g. "claude-opus-4-6"
														authorProvider: LLMProvider;
													}
												: A extends AgentAction.REVERT
													? { sha: string; reason?: string }
													: A extends AgentAction.BRANCH
														? { name: string }
														: A extends AgentAction.MERGE
															? { sourceBranch: string; targetBranch: string }
															: A extends AgentAction.HTTP_GET
																? { url: string; statusCode?: number }
																: A extends AgentAction.HTTP_POST
																	? { url: string; statusCode?: number }
																	: A extends AgentAction.MCP_CALL
																		? { tool: string; server?: string }
																		: A extends AgentAction.PLAN
																			? {
																					description: string;
																					provider?: string;
																					model?: string;
																					inputTokens?: number;
																					outputTokens?: number;
																					cacheWriteTokens?: number;
																					cacheReadTokens?: number;
																				}
																			: A extends AgentAction.REVIEW
																				? { target: string }
																				: A extends AgentAction.DECIDE
																					? {
																							decision: string;
																							rationale?: string;
																							stopReason?: string;
																							responseId?: string;
																						}
																					: A extends AgentAction.ASK_USER
																						? { question: string }
																						: A extends AgentAction.VERIFY_GATE
																							? {
																									gateId: string;
																									passed: boolean;
																								}
																							: A extends AgentAction.SCORE_R
																								? {
																										rId: string;
																										passed: boolean;
																									}
																								: A extends AgentAction.SEARCH_EXTERNAL
																									? {
																											query: string;
																											source?:
																												| "web"
																												| "github"
																												| "mcp-docs";
																										}
																									: A extends AgentAction.FETCH_DOCS
																										? {
																												library: string;
																												version?: string;
																												url?: string;
																											}
																										: A extends AgentAction.CITE
																											? {
																													claim: string;
																													source: string;
																													excerpt: string;
																													dateAccessed: string; // ISO date string
																												}
																											: A extends AgentAction.GATE_OPEN
																												? {
																														gateType:
																															| "human-1"
																															| "human-2"
																															| "human-3";
																														specId: string;
																													}
																												: A extends AgentAction.GATE_CLOSE
																													? {
																															gateType:
																																| "human-1"
																																| "human-2"
																																| "human-3";
																															specId: string;
																															durationMs?: number; // milliseconds gate was open
																														}
																													: A extends AgentAction.DISPATCH
																														? {
																																specId: string;
																																worktreePath: string;
																																branch: string;
																															}
																														: A extends AgentAction.AUDIT_PHASE
																															? {
																																	auditPhase:
																																		| "1"
																																		| "2";
																																	specId: string;
																																}
																															: A extends AgentAction.SPEC_WRITE
																																? {
																																		specId: string;
																																		priority?:
																																			| "P0"
																																			| "P1"
																																			| "P2";
																																	}
																																: A extends AgentAction.PHASE_START
																																	? {
																																			phase:
																																				| "audit"
																																				| "spec"
																																				| "implement"
																																				| "review"
																																				| "gate"
																																				| "merge";
																																			specId: string;
																																			pioneerBlocker?: boolean;
																																		}
																																	: A extends AgentAction.PHASE_END
																																		? {
																																				phase:
																																					| "audit"
																																					| "spec"
																																					| "implement"
																																					| "review"
																																					| "gate"
																																					| "merge";
																																				specId: string;
																																				outcome:
																																					| "completed"
																																					| "abandoned"
																																					| "failed";
																																				durationMs?: number;
																																			}
																																		: Record<
																																				string,
																																				unknown
																																			>;

// ─── Tool Decision Span Shape ─────────────────────────────────────────────────
// OBS-DECISION-01: Distinct span type for tool choice recording.

export interface ToolDecision {
	/** Actions the agent could have taken */
	available: AgentAction[];
	/** Actions the agent actually took */
	invoked: AgentAction[];
	/** Actions available but skipped  -  wrapper validates: skipped = available \ invoked */
	skipped: AgentAction[];
	/** Why (free text, max 1000 chars) */
	rationale: string;
	/** Identifier for where the decision was made: "pre-write", "pre-commit", "audit-completeness", "pre-approve" */
	decisionPoint: string;
}
