/**
 * OpenTelemetry Implementation of InstrumentationProvider
 *
 * Production-ready instrumentation using OpenTelemetry SDK.
 * Supports distributed tracing, context propagation, metrics, and trace-log correlation.
 *
 * Key Features:
 * - Pino instrumentation for automatic trace_id/span_id injection into logs
 * - W3C TraceContext propagation for distributed tracing
 * - Configurable sampling rates
 * - OTLP exporter for Axiom/Grafana/Jaeger
 */

import type { Tracer } from "@opentelemetry/api";
import {
	context,
	metrics,
	type Context as OTelContext,
	type Span as OTelSpan,
	SpanStatusCode as OTelSpanStatusCode,
	propagation,
	ROOT_CONTEXT,
	trace,
} from "@opentelemetry/api";
import { OTLPMetricExporter } from "@opentelemetry/exporter-metrics-otlp-http";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import { PgInstrumentation } from "@opentelemetry/instrumentation-pg";
import { PinoInstrumentation } from "@opentelemetry/instrumentation-pino";
import { resourceFromAttributes } from "@opentelemetry/resources";
import { MeterProvider, PeriodicExportingMetricReader } from "@opentelemetry/sdk-metrics";
import {
	BatchSpanProcessor,
	ConsoleSpanExporter,
	type SpanProcessor,
	TraceIdRatioBasedSampler,
} from "@opentelemetry/sdk-trace-base";
import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
import { ATTR_SERVICE_NAME, ATTR_SERVICE_VERSION } from "@opentelemetry/semantic-conventions";
import type {
	Attributes,
	Context,
	ContextCarrier,
	InstrumentationProvider,
	Span,
	SpanOptions,
	SpanStatusCode,
} from "@vreko/contracts";

export interface OTelConfig {
	/** Service name (e.g., 'vreko-api', 'vreko-vscode') */
	serviceName: string;
	/** Service version */
	serviceVersion?: string;
	/** Environment (dev, staging, production) */
	environment?: string;
	/** OTLP collector URL (e.g., 'http://localhost:4318/v1/traces') */
	collectorUrl?: string;
	/** Enable console exporter (for debugging) */
	enableConsole?: boolean;
	/** Sampling rate (0.0 - 1.0) */
	sampleRate?: number;
}

/**
 * OpenTelemetry Span Adapter
 * Wraps OTel span to match our Span interface
 */
class OTelSpanAdapter implements Span {
	constructor(private otelSpan: OTelSpan) {
		/* intentionally empty */
	}

	setAttribute(key: string, value: string | number | boolean): void {
		this.otelSpan.setAttribute(key, value);
	}

	setAttributes(attributes: Attributes): void {
		this.otelSpan.setAttributes(attributes);
	}

	addEvent(name: string, attributes?: Attributes): void {
		this.otelSpan.addEvent(name, attributes);
	}

	setStatus(status: { code: SpanStatusCode; message?: string }): void {
		this.otelSpan.setStatus({
			code: status.code,
			message: status.message,
		});
	}

	recordException(error: Error): void {
		this.otelSpan.recordException(error);
	}

	end(): void {
		this.otelSpan.end();
	}

	isRecording(): boolean {
		return this.otelSpan.isRecording();
	}
}

/**
 * OpenTelemetry Instrumentation Provider
 *
 * Implements the InstrumentationProvider interface with full OTel support.
 * Automatically injects trace context into Pino logs for seamless correlation.
 *
 * Note on Metrics (2026 Best Practice):
 * - Meter is initialized once and reused throughout application lifetime
 * - Metrics are no-ops until MeterProvider is registered at application startup
 * - To enable: Register MeterProvider with OTLP exporter in server initialization
 */
export class OTelInstrumentationProvider implements InstrumentationProvider {
	private tracer: Tracer;
	private provider: NodeTracerProvider;
	private meter: ReturnType<typeof metrics.getMeter>;

	constructor(config: OTelConfig) {
		// Create resource with service metadata
		const resource = resourceFromAttributes({
			[ATTR_SERVICE_NAME]: config.serviceName,
			[ATTR_SERVICE_VERSION]: config.serviceVersion || "unknown",
			"deployment.environment": config.environment || "development",
			"service.instance.id": process.pid.toString(),
			"host.name": process.env.HOSTNAME || "unknown",
			"process.pid": process.pid,
		});

		// Build span processors array (SDK 2.0 uses constructor option instead of addSpanProcessor)
		const spanProcessors: SpanProcessor[] = [];

		if (config.collectorUrl) {
			// OTLP exporter for Axiom/Grafana/Jaeger
			const otlpExporter = new OTLPTraceExporter({
				url: config.collectorUrl,
			});
			spanProcessors.push(new BatchSpanProcessor(otlpExporter));
		}

		if (config.enableConsole) {
			// Console exporter for debugging
			const consoleExporter = new ConsoleSpanExporter();
			spanProcessors.push(new BatchSpanProcessor(consoleExporter));
		}

		// Initialize tracer provider with optional sampling
		const samplingRate = config.sampleRate ?? 1.0;
		const sampler = new TraceIdRatioBasedSampler(samplingRate);

		this.provider = new NodeTracerProvider({
			resource,
			sampler,
			spanProcessors,
		});

		// Register provider globally
		this.provider.register();

		// Register Pino instrumentation for trace-log correlation
		// This auto-injects trace_id, span_id, trace_flags into every Pino log
		// within an active span context
		const pinoInstrumentation = new PinoInstrumentation({
			// Keep default log keys: trace_id, span_id, trace_flags
			// These match standard OTel semantic conventions
			disableLogSending: true, // Don't send logs via OTLP (we use Axiom transport directly)
			disableLogCorrelation: false, // Enable trace context injection
		});

		// Register PostgreSQL instrumentation for database query tracing
		// Captures all SQL queries executed through the pg driver
		const pgInstrumentation = new PgInstrumentation({
			// Add database query attributes to spans
			requireParentSpan: false, // Allow spans without parent (standalone queries)
			enhancedDatabaseReporting: true, // Include additional database attributes
		});

		// Manually patch Pino and PostgreSQL since we're initializing after module imports
		// This is safe because instrumentations handle patching gracefully
		try {
			pinoInstrumentation.enable();
			pgInstrumentation.enable();
		} catch {
			// Modules may already be loaded; instrumentations handle gracefully
		}

		// Get tracer instance
		this.tracer = trace.getTracer(config.serviceName, config.serviceVersion);

		// Get meter instance - created once, reused throughout application lifetime
		// This follows 2026 OTel best practice: Meter is expensive and meant to be reused
		this.meter = metrics.getMeter(config.serviceName, config.serviceVersion || "unknown");

		// Register MeterProvider with OTLP exporter for metrics
		try {
			if (config.collectorUrl) {
				const metricsUrl = config.collectorUrl.replace("/traces", "/metrics");
				const metricReader = new PeriodicExportingMetricReader({
					exporter: new OTLPMetricExporter({ url: metricsUrl }),
					exportIntervalMillis: 60000,
				});

				const meterProvider = new MeterProvider({
					resource,
					readers: [metricReader],
				});

				metrics.setGlobalMeterProvider(meterProvider);
			}
		} catch (_error) {}
	}

	startSpan(name: string, options?: SpanOptions): Span {
		const otelSpan = this.tracer.startSpan(name, {
			kind: options?.kind,
			attributes: options?.attributes,
			startTime: options?.startTime,
		});
		return new OTelSpanAdapter(otelSpan);
	}

	async withSpan<T>(name: string, fn: (span: Span) => Promise<T>, options?: SpanOptions): Promise<T> {
		// Use parent context if provided, otherwise use active context
		const parentCtx = options?.parent ? (options.parent as OTelContext) : context.active();

		return await this.tracer.startActiveSpan(
			name,
			{
				kind: options?.kind,
				attributes: options?.attributes,
				startTime: options?.startTime,
			},
			parentCtx, // Pass parent context here
			async (otelSpan) => {
				const span = new OTelSpanAdapter(otelSpan);
				try {
					const result = await fn(span);
					otelSpan.setStatus({ code: OTelSpanStatusCode.OK });
					return result;
				} catch (error) {
					otelSpan.recordException(error as Error);
					otelSpan.setStatus({
						code: OTelSpanStatusCode.ERROR,
						message: error instanceof Error ? error.message : String(error),
					});
					throw error;
				} finally {
					otelSpan.end();
				}
			},
		);
	}

	injectContext(carrier: ContextCarrier): void {
		// Inject current context into carrier (HTTP headers)
		propagation.inject(context.active(), carrier);
	}

	extractContext(carrier: ContextCarrier): Context | null {
		// Extract context from carrier using ROOT_CONTEXT as base to avoid pollution
		const extractedContext = propagation.extract(ROOT_CONTEXT, carrier);

		// Check if context has trace information
		const span = trace.getSpan(extractedContext);
		if (span?.spanContext().traceId) {
			return extractedContext as unknown as Context;
		}

		return null;
	}

	recordMetric(name: string, value: number, attributes?: Attributes): void {
		const counter = this.meter.createCounter(name);
		counter.add(value, attributes);
	}

	recordEvent(_name: string, _attributes?: Attributes): void {
		// No-op implementation - standalone events not yet implemented
		// Most events should be added to active span via span.addEvent()
		// This method is available for future standalone event support if needed
	}

	async shutdown(): Promise<void> {
		await this.provider.shutdown();
	}
}
