// ─── Conductor Session Insights (R-2-01) ─────────────────────────────────────

/**
 * Per-agent gate failure rate derived from Langfuse score data.
 */
export interface AgentGateFailureRate {
	agent: string;
	firstAttemptFailRate: number;
	sampleSize: number;
}

/**
 * Per-agent cost estimate from the last N runs.
 */
export interface AgentCostSummary {
	agent: string;
	avgCostUsd: number;
	runCount: number;
}

/**
 * Aggregated context for conductor session start.
 * Composes existing retro-queries without new HTTP calls.
 */
export interface ConductorInsights {
	gateFailureRatesByAgent: AgentGateFailureRate[];
	costByAgentLastNRuns: AgentCostSummary[];
	toolSkipRatesByRole: { role: string; skipCount: number; totalDecisions: number }[];
	staleSinceTimestamp: string;
}

/**
 * R-2-01: Aggregated conductor insights from the last N swarm runs.
 *
 * Composes:
 * - failedGatesInLastNRuns(n)  -  gate failures grouped by gate ID
 * - gatesFailingFirstAttempt()  -  first-attempt failure flag per gate (requires specId context)
 * - decisionsWithSkips()  -  tool skip counts per agent role
 *
 * Fire-and-forget safe: callers should treat all failures as advisory.
 * No new Langfuse Score types are introduced.
 */
export async function conductorSessionInsights(n = 20): Promise<ConductorInsights> {
	const staleSinceTimestamp = new Date().toISOString();

	// --- Gate failure rates by agent role --------------------------------
	// Use failedGatesInLastNRuns to get gate names. Gate names embed the
	// agent role convention: "R-<N>-<NN>" from spec IDs, or the raw rId.
	// We aggregate at the gate level (not per-agent here) since Langfuse
	// scores don't carry an agent field  -  this surfaces the most-failing gates.
	let rawGateFailures: FailedGateSummary[] = [];
	try {
		rawGateFailures = await failedGatesInLastNRuns(n);
	} catch {
		// Advisory  -  swallow, return empty
	}

	// Derive a simple per-gate failure entry from the raw summaries.
	// sampleSize = count of failures observed; firstAttemptFailRate is 1.0
	// for any gate that has appeared (all returned are failures).
	const gateFailureRatesByAgent: AgentGateFailureRate[] = rawGateFailures.map((g) => ({
		agent: g.rId,
		firstAttemptFailRate: 1.0,
		sampleSize: g.count,
	}));

	// --- Tool skip rates by role -----------------------------------------
	const toolSkipRatesByRole: { role: string; skipCount: number; totalDecisions: number }[] = [];
	const since = new Date(Date.now() - n * 24 * 60 * 60 * 1000); // last n days (proxy for last n runs)

	for (const role of Object.values(AgentRole)) {
		let decisions: ToolDecision[] = [];
		try {
			decisions = await decisionsWithSkips(role, since);
		} catch {
			// Advisory  -  skip this role
			continue;
		}
		if (decisions.length === 0) continue;
		const skipCount = decisions.reduce((sum, d) => sum + d.skipped.length, 0);
		toolSkipRatesByRole.push({
			role,
			skipCount,
			totalDecisions: decisions.length,
		});
	}

	// --- Cost by agent (advisory placeholder) ----------------------------
	// Langfuse usage/cost data is not yet available via the public API in a
	// per-agent aggregated form. This field is wired for future population.
	const costByAgentLastNRuns: AgentCostSummary[] = [];

	return {
		gateFailureRatesByAgent,
		costByAgentLastNRuns,
		toolSkipRatesByRole,
		staleSinceTimestamp,
	};
}
