/**
 * Neon Schema Migrations
 *
 * Helper to run the doc_embeddings schema migration on Neon.
 * Reads schema.sql and executes it via @neondatabase/serverless.
 *
 * @module infrastructure/neon/migrations
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { type NeonQueryFunction, neon } from "@neondatabase/serverless";

// Edge Runtime compatible: convert import.meta.url string to path
// Using dirname() is required for Edge Runtime compatibility
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

/**
 * Run the documentation intelligence schema migration
 *
 * @param connectionString - Neon connection string (use direct URL for migrations, not pooled)
 * @returns Migration result
 *
 * @example
 * ```typescript
 * await runMigration(process.env.NEON_DIRECT_URL!);
 * ```
 */
export async function runMigration(connectionString: string): Promise<{
	success: boolean;
	error?: string;
}> {
	try {
		const sql: NeonQueryFunction<false, false> = neon(connectionString);

		// Read schema.sql
		const schemaPath = join(__dirname, "schema.sql");
		const schemaSql = readFileSync(schemaPath, "utf-8");

		// Execute migration (Neon supports multistatement SQL)
		await sql(schemaSql);

		return { success: true };
	} catch (error) {
		return {
			success: false,
			error: error instanceof Error ? error.message : String(error),
		};
	}
}

/**
 * Verify schema is correctly installed
 *
 * @param connectionString - Neon connection string
 * @returns Verification result with details
 */
export async function verifySchema(connectionString: string): Promise<{
	valid: boolean;
	checks: {
		tableExists: boolean;
		hnswIndexExists: boolean;
		hybridSearchFunctionExists: boolean;
	};
	error?: string;
}> {
	try {
		const sql: NeonQueryFunction<false, false> = neon(connectionString);

		// Check if table exists
		const tableCheck = await sql`
      SELECT EXISTS (
        SELECT FROM information_schema.tables 
        WHERE table_name = 'doc_embeddings'
      ) as exists
    `;
		const tableExists = tableCheck[0]?.exists === true;

		// Check if HNSW index exists
		const indexCheck = await sql`
      SELECT EXISTS (
        SELECT FROM pg_indexes 
        WHERE indexname = 'doc_embeddings_hnsw_idx'
      ) as exists
    `;
		const hnswIndexExists = indexCheck[0]?.exists === true;

		// Check if hybrid_search function exists
		const functionCheck = await sql`
      SELECT EXISTS (
        SELECT FROM pg_proc 
        WHERE proname = 'hybrid_search'
      ) as exists
    `;
		const hybridSearchFunctionExists = functionCheck[0]?.exists === true;

		const valid = tableExists && hnswIndexExists && hybridSearchFunctionExists;

		return {
			valid,
			checks: {
				tableExists,
				hnswIndexExists,
				hybridSearchFunctionExists,
			},
		};
	} catch (error) {
		return {
			valid: false,
			checks: {
				tableExists: false,
				hnswIndexExists: false,
				hybridSearchFunctionExists: false,
			},
			error: error instanceof Error ? error.message : String(error),
		};
	}
}
