/**
 * wrapper.ts  -  Typed Observability Wrapper
 *
 * All swarm agent telemetry routes through this module.
 * Enforces the AgentAction enum at compile time (OBS-VOCAB-04).
 * Validates metadata keys (OBS-VOCAB-05).
 * Routes spans through otel-emit.ts via the Collector path (OBS-BOUNDARY-03).
 *
 * DO NOT call otel-emit.ts directly  -  use this wrapper.
 * DO NOT add @langfuse/node imports here  -  Collector-only path is the locked invariant.
 */

import { randomUUID } from "node:crypto";
import type { ActionPayload, ToolDecision } from "./vocabulary.js";
import { AgentAction, type AgentRole } from "./vocabulary.js";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SpanHandle {
	spanId: string;
	traceId: string;
	end(): void;
}

export interface RecordActionOptions {
	traceId: string;
	parentSpanId?: string;
	agentRole: AgentRole;
	/** Transport: always "collector"  -  SDK-direct is a no-op stub for future use (OBS-BOUNDARY-03) */
	transport?: "collector" | "sdk";
	/** Additional metadata. Keys: camelCase /^[a-zA-Z][a-zA-Z0-9]*$/, values ≤200 chars. */
	metadata?: Record<string, string>;
	/**
	 * OBS-VOCAB-02: Spec identifier (e.g. "META-OBS-01"). When combined with phaseId,
	 * used to build the Langfuse trace name: "{agentRole}:{specId}/{phaseId}".
	 */
	specId?: string;
	/**
	 * OBS-VOCAB-02: Phase identifier (e.g. "phase-1"). Combined with specId for trace name.
	 */
	phaseId?: string;
	/**
	 * OBS-VOCAB-07: Model identifier for the agent run (e.g. "claude-sonnet-4-6").
	 * Emitted as metadata.model on the span. Defaults to process.env.VREKO_AGENT_MODEL.
	 */
	model?: string;
	/**
	 * Langfuse user.id  -  maps to the developer or workspace that triggered this run.
	 * Enables per-user views in the Langfuse UI.
	 */
	userId?: string;
	/**
	 * vreko.workspace.id  -  workspace-scoped attribution for multi-workspace deployments.
	 * Compute via generateWorkspaceId() from @vreko/workspace-identity at the call site.
	 */
	workspaceId?: string;
	/**
	 * deployment.environment  -  separates prod/dogfood/local traces.
	 * Falls back to LANGFUSE_TRACING_ENVIRONMENT env var, then "unknown".
	 */
	environment?: string;
	/**
	 * vreko.prompt.version  -  prompt template version for Langfuse experiment diffing.
	 * E.g. "conductor-v2", "spec-writer-v1.1".
	 */
	promptVersion?: string;
}

export interface RecordDecisionOptions {
	traceId: string;
	parentSpanId?: string;
	agentRole: AgentRole;
	transport?: "collector" | "sdk";
	metadata?: Record<string, string>;
	/**
	 * OBS-VOCAB-03: Spec and phase context for trace naming.
	 * Name formula: "{agentRole}:{specId}/{phaseId}" when both present;
	 * falls back to "{agentRole}:tool_decision".
	 */
	specId?: string;
	phaseId?: string;
}

export interface RecordGateOptions {
	traceId: string;
	specId?: string;
	phaseId?: string;
	transport?: "collector" | "sdk";
	/**
	 * OBS-VOCAB-03: Optional agent role  -  used in trace name formula:
	 * "{agentRole}:{specId}/{phaseId}" when all three are set.
	 * Falls back to "gate:{specId}/{phaseId}" or "verify_gate:{rId}".
	 */
	agentRole?: AgentRole;
	/**
	 * ISO timestamp of when the gate was opened (for wait duration calculation).
	 * When provided, emits vreko.gate.openedAt and vreko.gate.waitDurationMs attributes.
	 */
	gateOpenedAt?: string;
}

// ─── Startup validation ───────────────────────────────────────────────────────

/**
 * LANGFUSE-03: Validate Langfuse env vars at process boot.
 * Call once from every entry point that initializes Langfuse.
 * Throws on misconfiguration  -  fail fast rather than emitting to a wrong endpoint.
 */
export function validateLangfuseConfig(): void {
	const baseUrl = process.env.LANGFUSE_BASE_URL;
	const secretKey = process.env.LANGFUSE_SECRET_KEY;
	const publicKey = process.env.LANGFUSE_PUBLIC_KEY;

	if (!baseUrl?.startsWith("http")) {
		throw new Error(`LANGFUSE_BASE_URL invalid: expected URL, got "${baseUrl?.slice(0, 20)}..."`);
	}
	if (!secretKey?.startsWith("sk-lf-")) {
		throw new Error(`LANGFUSE_SECRET_KEY invalid: expected key starting with sk-lf-`);
	}
	if (!publicKey?.startsWith("pk-lf-")) {
		throw new Error(`LANGFUSE_PUBLIC_KEY invalid: expected key starting with pk-lf-`);
	}
}

// ─── Metadata validation ──────────────────────────────────────────────────────

const METADATA_KEY_RE = /^[a-zA-Z][a-zA-Z0-9]*$/;
const METADATA_VALUE_MAX = 200;

/**
 * OBS-VOCAB-05: Validate propagated metadata keys and values.
 * Keys must match /^[a-zA-Z][a-zA-Z0-9]*$/ (camelCase, no hyphens/underscores).
 * Values must be ≤200 chars.
 * Throws on violation  -  silent dropping is the exact failure mode this spec prevents.
 */
export function validateMetadata(metadata: Record<string, string>): void {
	for (const [key, value] of Object.entries(metadata)) {
		if (!METADATA_KEY_RE.test(key)) {
			throw new Error(
				`[observability] Invalid metadata key "${key}": must match /^[a-zA-Z][a-zA-Z0-9]*$/ (camelCase, no hyphens or underscores). Langfuse silently drops non-conforming keys.`,
			);
		}
		if (value.length > METADATA_VALUE_MAX) {
			throw new Error(
				`[observability] Metadata value for key "${key}" is ${value.length} chars, exceeds ${METADATA_VALUE_MAX} char limit. Langfuse silently drops oversized values.`,
			);
		}
	}
}

// ─── Trace name builder ───────────────────────────────────────────────────────

/**
 * OBS-VOCAB-02 / OBS-VOCAB-03: Build a readable Langfuse trace name.
 * Formula: "{role}:{specId}/{phaseId}" when specId+phaseId are present;
 * falls back to "{role}:{fallback}" (e.g. "{role}:{action}", "{role}:tool_decision").
 */
function buildTraceName(
	role: string,
	specId: string | undefined,
	phaseId: string | undefined,
	fallback: string,
): string {
	if (specId && phaseId) return `${role}:${specId}/${phaseId}`;
	return `${role}:${fallback}`;
}

// ─── OTLP emission (Collector path) ──────────────────────────────────────────

// Collector-only path: emit to the local/configured OTLP Collector so redaction,
// batching, and downstream export policy are never bypassed from this wrapper.
// Resolution order:
//   1. COLLECTOR_ENDPOINT  -  explicit override (used by swarm wrapper directly)
//   2. OTLP_ENDPOINT       -  legacy alias
//   3. OTEL_EXPORTER_OTLP_ENDPOINT  -  standard OTel SDK base URL (no path); append /v1/traces
//   4. hardcoded default   -  local Collector on :4318
const _otelBase = process.env.OTEL_EXPORTER_OTLP_ENDPOINT;
const COLLECTOR_ENDPOINT =
	process.env.COLLECTOR_ENDPOINT ??
	process.env.OTLP_ENDPOINT ??
	(_otelBase ? `${_otelBase.replace(/\/+$/, "")}/v1/traces` : "http://localhost:4318/v1/traces");
const NETWORK_TIMEOUT_MS = 500;

function nanoNow(): string {
	return String(BigInt(Date.now()) * 1_000_000n);
}

function newSpanId(): string {
	return randomUUID().replace(/-/g, "").slice(0, 16);
}

function buildAuthHeader(): string | null {
	const pk = process.env.LANGFUSE_PUBLIC_KEY;
	const sk = process.env.LANGFUSE_SECRET_KEY;
	if (pk && sk) {
		return `Basic ${Buffer.from(`${pk}:${sk}`).toString("base64")}`;
	}
	return null;
}

interface OtlpAttribute {
	key: string;
	value: { stringValue?: string; boolValue?: boolean; intValue?: string };
}

function toAttr(key: string, value: string | boolean | number): OtlpAttribute {
	if (typeof value === "boolean") return { key, value: { boolValue: value } };
	if (typeof value === "number") return { key, value: { intValue: String(value) } };
	return { key, value: { stringValue: String(value) } };
}

async function emitSpanToCollector(
	traceId: string,
	spanId: string,
	parentSpanId: string | undefined,
	name: string,
	attributes: Record<string, string | boolean | number>,
	startNano: string,
	endNano?: string,
): Promise<void> {
	const auth = buildAuthHeader();
	if (!auth) return; // credentials not present  -  no-op in test/CI environments

	const attrs: OtlpAttribute[] = Object.entries(attributes).map(([k, v]) => toAttr(k, v));

	const span: Record<string, unknown> = {
		traceId,
		spanId,
		name,
		kind: 1,
		startTimeUnixNano: startNano,
		endTimeUnixNano: endNano ?? nanoNow(),
		attributes: attrs,
		status: { code: 0 },
	};
	if (parentSpanId) span.parentSpanId = parentSpanId;

	const payload = {
		resourceSpans: [
			{
				resource: {
					attributes: [
						toAttr("gen_ai.workflow.name", "vreko-swarm"),
						toAttr("service.name", "vreko-observability"),
					],
				},
				scopeSpans: [
					{
						scope: { name: "vreko.swarm.observability", version: "1.0.0" },
						spans: [span],
					},
				],
			},
		],
	};

	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(), NETWORK_TIMEOUT_MS);
	try {
		await fetch(COLLECTOR_ENDPOINT, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				Authorization: auth,
				"x-langfuse-ingestion-version": "4",
			},
			body: JSON.stringify(payload),
			signal: controller.signal,
		});
	} catch {
		// Fire-and-forget  -  telemetry never blocks agent execution
	} finally {
		clearTimeout(timer);
	}
}

// ─── recordAction ─────────────────────────────────────────────────────────────

/**
 * OBS-VOCAB-02: Typed wrapper for emitting agent action spans.
 *
 * The `action` parameter is constrained to the AgentAction enum  -  TypeScript
 * rejects string literals at the call site (OBS-VOCAB-04).
 *
 * The `payload` parameter is a discriminated union keyed by action type  -
 * TypeScript enforces required fields per action (OBS-VOCAB-03).
 *
 * @throws if metadata fails key/value validation (OBS-VOCAB-05)
 */
export async function recordAction<A extends AgentAction>(
	action: A,
	payload: ActionPayload<A>,
	options: RecordActionOptions,
): Promise<SpanHandle> {
	// OBS-VOCAB-05: validate metadata eagerly  -  do not silently drop
	if (options.metadata) {
		validateMetadata(options.metadata);
	}

	const spanId = newSpanId();
	const startNano = nanoNow();

	// OBS-VOCAB-02: build readable trace name  -  "{agentRole}:{specId}/{phaseId}" or "{agentRole}:{action}"
	const traceName = buildTraceName(options.agentRole, options.specId, options.phaseId, action);

	// OBS-VOCAB-07: resolve model  -  explicit option takes precedence over env var
	const resolvedModel = options.model ?? process.env.VREKO_AGENT_MODEL;

	const attributes: Record<string, string | boolean | number> = {
		"gen_ai.operation.name": "execute_tool",
		"vreko.agent.role": options.agentRole,
		"vreko.action": action,
		"vreko.trace.name": traceName,
		"gen_ai.conversation.id": options.traceId,
	};

	// OBS-VOCAB-07: emit model as gen_ai.request.model (OTEL semconv  -  Langfuse shows model names from this attribute)
	if (resolvedModel) {
		attributes["gen_ai.request.model"] = resolvedModel;
	}

	// User + workspace attribution (Langfuse user tracking)
	if (options.userId) attributes["user.id"] = options.userId;
	if (options.workspaceId) attributes["vreko.workspace.id"] = options.workspaceId;

	// Environment: explicit option > LANGFUSE_TRACING_ENVIRONMENT env var > "unknown"
	attributes["deployment.environment"] = options.environment ?? process.env.LANGFUSE_TRACING_ENVIRONMENT ?? "unknown";

	// Prompt version for Langfuse experiment diffing
	if (options.promptVersion) attributes["vreko.prompt.version"] = options.promptVersion;

	// Merge payload fields as attributes (string values only, for OTLP compatibility)
	for (const [k, v] of Object.entries(payload as Record<string, unknown>)) {
		if (typeof v === "string" || typeof v === "number" || typeof v === "boolean") {
			attributes[`vreko.action.${k}`] = v as string | number | boolean;
		}
	}

	// Merge additional metadata
	if (options.metadata) {
		for (const [k, v] of Object.entries(options.metadata)) {
			attributes[`vreko.meta.${k}`] = v;
		}
	}

	// SDK-direct transport is a no-op stub  -  Collector path is locked (OBS-BOUNDARY-03).
	// Future SDK-direct activation requires an ADR amendment before wiring.
	if (options.transport === "sdk") {
		// no-op: SDK-direct path not yet activated. Span is silently dropped.
		return {
			spanId,
			traceId: options.traceId,
			end: () => {},
		};
	}

	// Collector path (default): emit via Langfuse OTLP endpoint.
	// In production, otel-emit.ts hook routes spans through localhost:4318 → OTel Collector → Langfuse.
	// This direct emission is the secondary path used for integration testing and programmatic wrappers.
	await emitSpanToCollector(options.traceId, spanId, options.parentSpanId, traceName, attributes, startNano);

	const endNano = nanoNow();

	return {
		spanId,
		traceId: options.traceId,
		end: () => {
			// Span end is emitted inline above (fire-and-forget model).
			// This handle is returned for callers that want to attach child spans.
		},
	};
}

// ─── recordDecision ───────────────────────────────────────────────────────────

/** OBS-DECISION-04: Validate decision set math and rationale length. */
function validateDecision(decision: ToolDecision): void {
	// Subset check must run before set math  -  invalid invoked makes set math nonsensical.
	for (const a of decision.invoked) {
		if (!decision.available.includes(a)) {
			throw new Error(
				`[observability] recordDecision: invoked action "${a}" is not in available set at "${decision.decisionPoint}".`,
			);
		}
	}
	const invokedSet = new Set(decision.invoked);
	const expectedSkipped = decision.available.filter((a) => !invokedSet.has(a));
	const exp = [...expectedSkipped].sort().join(",");
	const act = [...decision.skipped].sort().join(",");
	if (exp !== act) {
		throw new Error(
			`[observability] recordDecision set math invalid at "${decision.decisionPoint}": ` +
				`expected skipped=[${exp}] (available\\invoked) but got skipped=[${act}]. ` +
				`Agent must not misreport available actions.`,
		);
	}
	if (decision.rationale.length > 1000) {
		throw new Error(
			`[observability] recordDecision rationale at "${decision.decisionPoint}" exceeds 1000 char limit.`,
		);
	}
}

/** Build decision span attributes. */
function buildDecisionAttributes(
	decision: ToolDecision,
	options: RecordDecisionOptions,
): Record<string, string | boolean | number> {
	const hasSkipped = decision.skipped.length > 0;
	const attrs: Record<string, string | boolean | number> = {
		"gen_ai.operation.name": "tool_decision",
		"vreko.agent.role": options.agentRole,
		"vreko.decision.point": decision.decisionPoint,
		"vreko.decision.available": decision.available.join(","),
		"vreko.decision.invoked": decision.invoked.join(","),
		"vreko.decision.skipped": decision.skipped.join(","),
		"vreko.decision.rationale": decision.rationale.slice(0, 1000),
		"vreko.decision.hasSkipped": hasSkipped,
		"gen_ai.conversation.id": options.traceId,
	};
	// OBS-DECISION-05: auto-apply "decision:has-skipped" tag
	if (hasSkipped) attrs["vreko.tag"] = "decision:has-skipped";
	if (options.metadata) {
		for (const [k, v] of Object.entries(options.metadata)) attrs[`vreko.meta.${k}`] = v;
	}
	return attrs;
}

/**
 * OBS-DECISION-02: Emit a tool_decision span.
 * Validates set math (OBS-DECISION-04) and auto-tags skipped decisions (OBS-DECISION-05).
 * @throws on set math violation, metadata error, or rationale overflow
 */
export async function recordDecision(decision: ToolDecision, options: RecordDecisionOptions): Promise<SpanHandle> {
	validateDecision(decision);
	if (options.metadata) validateMetadata(options.metadata);
	if (options.transport === "sdk") return { spanId: newSpanId(), traceId: options.traceId, end: () => {} };
	const spanId = newSpanId();
	// OBS-VOCAB-03: build readable trace name for dashboard
	const traceName = buildTraceName(options.agentRole, options.specId, options.phaseId, "tool_decision");
	const attributes = buildDecisionAttributes(decision, options);
	attributes["vreko.trace.name"] = traceName;
	await emitSpanToCollector(options.traceId, spanId, options.parentSpanId, traceName, attributes, nanoNow());
	return { spanId, traceId: options.traceId, end: () => {} };
}

// ─── recordGate ───────────────────────────────────────────────────────────────

/**
 * OBS-SCORE-02: Emit a gate verification result as a Langfuse Score + span.
 *
 * Every shell-verifiable gate in every spec should call this after running
 * the gate command. Emits a span with score attributes and updates trace
 * metadata with lastGate and gate:passed / gate:failed tag.
 *
 * Score schema matches Langfuse Score API:
 *   { name: rId, value: 0|1, dataType: "BOOLEAN", comment: output, traceId }
 */
export async function recordGate(
	rId: string,
	passed: boolean,
	output: string,
	traceId: string,
	options?: RecordGateOptions,
): Promise<void> {
	const spanId = newSpanId();
	const startNano = nanoNow();

	// OBS-VOCAB-03: build readable trace name  -  "{agentRole}:{specId}/{phaseId}" or "gate:{specId}/{phaseId}" or "verify_gate:{rId}"
	const roleOrGate = options?.agentRole ?? "gate";
	const traceName = buildTraceName(roleOrGate, options?.specId, options?.phaseId, `verify_gate:${rId}`);

	const attributes: Record<string, string | boolean | number> = {
		"gen_ai.operation.name": "verify_gate",
		"vreko.r.id": rId,
		"vreko.gate.passed": passed,
		"vreko.gate.output": output.slice(0, 500), // truncate long outputs
		"vreko.gate.tag": passed ? "gate:passed" : "gate:failed",
		"vreko.gate.lastGate": rId,
		"vreko.trace.name": traceName,
		"gen_ai.conversation.id": traceId,
	};

	if (options?.specId) attributes["vreko.spec.id"] = options.specId;
	if (options?.phaseId) attributes["vreko.phase.name"] = options.phaseId;

	if (options?.gateOpenedAt) {
		attributes["vreko.gate.openedAt"] = options.gateOpenedAt;
		const waitMs = Date.now() - new Date(options.gateOpenedAt).getTime();
		if (!Number.isNaN(waitMs) && waitMs >= 0) {
			attributes["vreko.gate.waitDurationMs"] = waitMs;
		}
	}

	if (options?.transport === "sdk") return;

	await emitSpanToCollector(traceId, spanId, undefined, traceName, attributes, startNano);
}

// ─── emitPhaseEvent ───────────────────────────────────────────────────────────

/**
 * Convenience wrapper for pipeline phase boundary spans.
 * Emits PHASE_START or PHASE_END via recordAction with consistent attribute population.
 * Use this at the start and end of each pipeline stage (audit/spec/implement/review/gate/merge).
 */
export async function emitPhaseEvent(
	event: "start" | "end",
	phase: "audit" | "spec" | "implement" | "review" | "gate" | "merge",
	options: {
		traceId: string;
		specId: string;
		agentRole: AgentRole;
		outcome?: "completed" | "abandoned" | "failed"; // required for "end" events
		durationMs?: number;
		pioneerBlocker?: boolean;
		priority?: "P0" | "P1" | "P2";
		model?: string;
		userId?: string;
		workspaceId?: string;
	},
): Promise<SpanHandle> {
	if (event === "start") {
		return recordAction(
			AgentAction.PHASE_START,
			{ phase, specId: options.specId, pioneerBlocker: options.pioneerBlocker },
			{
				traceId: options.traceId,
				agentRole: options.agentRole,
				specId: options.specId,
				phaseId: phase,
				model: options.model,
				userId: options.userId,
				workspaceId: options.workspaceId,
				metadata: options.priority ? { priority: options.priority } : undefined,
			},
		);
	}
	return recordAction(
		AgentAction.PHASE_END,
		{
			phase,
			specId: options.specId,
			outcome: options.outcome ?? "completed",
			durationMs: options.durationMs,
		},
		{
			traceId: options.traceId,
			agentRole: options.agentRole,
			specId: options.specId,
			phaseId: phase,
			model: options.model,
			userId: options.userId,
			workspaceId: options.workspaceId,
		},
	);
}

// ─── emitRatchetScores ────────────────────────────────────────────────────────

/**
 * Emit ratchet delta counts as Langfuse Scores.
 * Call at merge time with before/after counts for each tracked ratchet.
 * Each ratchet emits one score: value=true (improved or unchanged), value=false (regressed).
 * A lower count is an improvement (e.g. fewer skipped tests = better).
 */
export async function emitRatchetScores(
	ratchets: Record<string, { before: number; after: number }>,
	traceId: string,
	specId: string,
	options?: { agentRole?: AgentRole },
): Promise<void> {
	const emits = Object.entries(ratchets).map(([name, { before, after }]) => {
		const improved = after <= before; // lower count = improved or unchanged
		const output = `before=${before} after=${after} delta=${after - before}`;
		return recordGate(`ratchet:${name}`, improved, output, traceId, {
			traceId,
			specId,
			agentRole: options?.agentRole,
		});
	});
	await Promise.all(emits);
}

// ─── Re-export vocabulary ─────────────────────────────────────────────────────

export type { ActionPayload, ToolDecision } from "./vocabulary.js";
// AgentAction and AgentRole are value-imported above and re-exported here
export { AgentAction, AgentRole } from "./vocabulary.js";
